func sortedPending(pending []pendingEntry) []pendingEntry {
        out := append([]pendingEntry(nil), pending...)
        sort.SliceStable(out, func(i, j int) bool {
                if out[i].ts.Equal(out[j].ts) {
                        return out[i].id < out[j].id
                }
                return out[i].ts.Before(out[j].ts)
        })
        return out
}

func sortedOpenSessions(m map[string]carriedSession) []carriedSession {
        out := make([]carriedSession, 0, len(m))
        for _, s := range m {
                out = append(out, s)
        }
        sort.SliceStable(out, func(i, j int) bool {
                if out[i].lastTs.Equal(out[j].lastTs) {
                        return out[i].user < out[j].user
                }
                return out[i].lastTs.Before(out[j].lastTs)
        })
        return out
}

func sortedCarriedSessions(m map[string]carriedSession) []carriedSession {
        return sortedOpenSessions(m)
