		case "--rates-strict":
			opts.ratesStrict = true
		case "--rates-max-staleness":
			opts.ratesMaxStale = parseIntFlag(args, &i, "--rates-max-staleness")
		case "--ingest-id":
			opts.ingestID = nextArg(args, &i)
			opts.ingestIDSet = true
		case "--out-parquet-manifest":
			opts.manifest = nextArg(args, &i)
			opts.manifestSet = true
		case "--manifest-signature":
