	bucketName := map[int]string{0: "accepted", 1: "duplicate", 2: "invalid", 3: "late", 4: "unresolved_chargeback"}
	var rejects []Reject
	var auditEntries []auditLogEntry
	var minTs, maxTs time.Time
	hasMin, hasMax := false, false
	totalUSD := 0.0

	watermark := st.maxTs
	if !st.hasMax {
		watermark = time.Time{}
	}
	for _, raw := range events {
		ctx := newContext(raw)
		bucket := 0
		reason := ""
		var ev *Event
		if raw.Invalid {
			bucket, reason = 2, "invalid_json"
		} else {
			ev, reason = parseEvent(ctx, rt, opts.ratesStrict, opts.ratesMaxStale)
			if ev == nil {
				switch reason {
				case "duplicate":
					bucket = 1
				case "invalid", "invalid_json", "bad_type", "bad_ts", "missing_id", "missing_ts", "missing_type", "missing_user", "schema_version", "missing_amount", "bad_amount", "missing_currency", "bad_currency", "fx_unknown_currency", "fx_no_rate_for_date", "fx_bad_rate", "missing_ref_id":
					bucket = 2
				case "late":
					bucket = 3
				case "unresolved_chargeback":
					bucket = 4
				default:
					bucket = 2
				}
			} else if seen[ev.ID] {
				bucket, reason = 1, "duplicate"
			} else if opts.watermarkLag >= 0 && ev.TS.Before(watermark.Add(-time.Duration(opts.watermarkLag)*time.Second)) {
				bucket, reason = 3, "late"
			} else {
				bucket = 0
				reason = "accepted"
				seen[ev.ID] = true
				totalUSD += ev.USD
				if !hasMin || ev.TS.Before(minTs) {
					minTs = ev.TS
					hasMin = true
				}
				if !hasMax || ev.TS.After(maxTs) {
					maxTs = ev.TS
					hasMax = true
				}
				watermark = ev.TS
			}
		}
		bucketCounts[bucketName[bucket]]++
		if bucket != 0 {
			rejects = append(rejects, Reject{Bucket: bucket, Event: raw.Raw})
			auditEntries = append(auditEntries, auditLogEntry{Shard: raw.Shard, Line: raw.Line, ID: ctxID(ctx), TS: ctxTS(ctx), Type: ctxType(ctx), Bucket: bucketName[bucket], Reason: reason, Event: raw.Raw})
		} else {
			auditEntries = append(auditEntries, auditLogEntry{Shard: raw.Shard, Line: raw.Line, ID: ev.ID, TS: formatTS(ev.TS), Type: ev.Type, Bucket: bucketName[bucket], Reason: reason, Event: raw.Raw})
		}
		for si := range shards {
			if shards[si].Name == raw.Shard {
				if bucket == 0 {
					shards[si].EventsAccepted++
				}
				break
			}
		}
	}

	out := summaryOutput{
		TotalEvents: len(events),
		AcceptedEvents: bucketCounts["accepted"],
		RejectedEvents: bucketCounts["duplicate"] + bucketCounts["invalid"] + bucketCounts["late"] + bucketCounts["unresolved_chargeback"],
		TotalUSD: Money(roundMoney(totalUSD)),
		Anomalies: map[string]int{
			"duplicate": bucketCounts["duplicate"],
			"invalid": bucketCounts["invalid"],
			"late": bucketCounts["late"],
			"unresolved_chargeback": bucketCounts["unresolved_chargeback"],
		},
		RunIndex: runIndex,
	}
	if hasMax {
		s := formatTS(maxTs)
		out.Watermark = &s
	} else if st.hasMax {
		s := formatTS(st.maxTs)
		out.Watermark = &s
	}

	summaryData, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return err
	}
	summaryData = append(summaryData, '\n')
	if err := atomicWriteFile(opts.output, summaryData); err != nil {
		return err
	}

	rejectsData, err := json.MarshalIndent(rejects, "", "  ")
	if err != nil {
		return err
	}
	rejectsData = append(rejectsData, '\n')
	if err := atomicWriteFile(opts.rejects, rejectsData); err != nil {
		return err
	}

	if opts.stateOut != "" {
		stateData := buildStateOut(maxTs, hasMax, st, sortedSeenIDs(seen), sortedPending(pending), sortedOpenSessions(openSessions), runIndex)
		if err := atomicWriteFile(opts.stateOut, stateData); err != nil {
			return err
		}
	}

	if opts.auditLog != "" {
		var lines []string
		for _, e := range auditEntries {
			b, _ := json.Marshal(e)
			lines = append(lines, string(b))
		}
		auditData := []byte(strings.Join(lines, "\n"))
		if len(auditData) > 0 {
			auditData = append(auditData, '\n')
		}
		if err := atomicWriteFile(opts.auditLog, auditData); err != nil {
			return err
		}
	}

	if opts.auditLogDigest != "" {
		digest := auditDigestOutput{
			SchemaVersion: "eventq.digest/v1",
			RatesDigest: ratesDigest,
			BucketCounts: bucketCounts,
			EventCount: len(events),
		}
		digestData, err := json.MarshalIndent(digest, "", "  ")
		if err != nil {
			return err
		}
		digestData = append(digestData, '\n')
		if err := atomicWriteFile(opts.auditLogDigest, digestData); err != nil {
			return err
		}
	}

	if opts.manifestSet {
		if err := writeManifest(opts, shards, runIndex, ratesDigest, bucketCounts, minTs, hasMin, maxTs, hasMax); err != nil {
			return err
		}
	}
	return nil
}

func ctxID(ctx *eventContext) string {
	if ctx.ID != nil {
		return *ctx.ID
	}
	return ""
}

func ctxTS(ctx *eventContext) string {
	if ctx.TS != nil {
		return *ctx.TS
	}
	return ""
}

func ctxType(ctx *eventContext) string {
	if ctx.Type != nil {
		return *ctx.Type
	}
	return ""
}

func writeManifest(opts cliOptions, shards []inputShardInfo, runIndex int, ratesDigest string, bucketCounts map[string]int, minTs time.Time, hasMin bool, maxTs time.Time, hasMax bool) error {
	sort.Slice(shards, func(i, j int) bool { return shards[i].Name < shards[j].Name })
	ms := make([]manifestShard, 0, len(shards))
	for _, s := range shards {
		ms = append(ms, manifestShard{
			Shard: s.Name,
			SHA256: s.SHA256,
			Bytes: s.Bytes,
			EventsTotal: s.EventsTotal,
			EventsAccepted: s.EventsAccepted,
		})
	}

	outputs := manifestOutputs{}
	o, err := manifestFileOutputFor(opts.output)
	if err != nil {
		return err
	}
	outputs.Summary = o
	o, err = manifestFileOutputFor(opts.rejects)
	if err != nil {
		return err
	}
	outputs.Rejects = o
	if opts.stateOut != "" {
		o, err = manifestFileOutputFor(opts.stateOut)
		if err != nil {
			return err
		}
		outputs.State = o
	}
	if opts.auditLog != "" {
		o, err = manifestFileOutputFor(opts.auditLog)
		if err != nil {
			return err
		}
		outputs.AuditLog = o
	}
	if opts.auditLogDigest != "" {
		o, err = manifestFileOutputFor(opts.auditLogDigest)
		if err != nil {
			return err
		}
		outputs.AuditDigest = o
	}

	window := manifestWindow{
		EventsAcceptedTotal: bucketCounts["accepted"],
		EventsRejectedTotal: bucketCounts["duplicate"] + bucketCounts["invalid"] + bucketCounts["late"] + bucketCounts["unresolved_chargeback"],
		BucketCounts: bucketCounts,
	}
	if hasMin {
		s := formatTS(minTs)
		window.MinTs = &s
	}
	if hasMax {
		s := formatTS(maxTs)
		window.MaxTs = &s
	}

	var ingestID *string
	if opts.ingestIDSet {
		ingestID = &opts.ingestID
	}
	manifest := manifestOutput{
		SchemaVersion: manifestSchemaVersion,
		IngestID: ingestID,
		RunIndex: runIndex,
		RatesDigest: ratesDigest,
		InputShards: ms,
		Outputs: outputs,
		Window: window,
	}
	data, err := json.MarshalIndent(manifest, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	tmp := opts.manifest + ".tmp"
	if err := os.WriteFile(tmp, data, 0644); err != nil {
		return err
	}
	if err := os.Rename(tmp, opts.manifest); err != nil {
		_ = os.Remove(tmp)
		return err
	}

	if opts.signatureSet {
		h, b, err := fileDigest(opts.manifest)
		if err != nil {
			return err
		}
		signedAt := "1970-01-01T00:00:00Z"
		if window.MaxTs != nil {
			signedAt = *window.MaxTs
		}
		sig := signatureOutput{
			ManifestPath: filepath.Base(opts.manifest),
			ManifestSHA256: h,
			ManifestBytes: b,
			SignedAtUTC: signedAt,
			ToolVersion: toolVersion,
		}
		sigData, err := json.MarshalIndent(sig, "", "  ")
		if err != nil {
			return err
		}
		sigData = append(sigData, '\n')
		if err := atomicWriteFile(opts.signature, sigData); err != nil {
			return err
		}
	}
	return nil
}
