package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

var ingestIDRE = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_.:-]*$`)

type cliConfig struct {
	inputDir         string
	ratesPath        string
	outputPath       string
	rejectsPath      string
	sessionGap       int
	watermarkLag     int
	stateIn          string
	stateOut         string
	pendingTTL       int
	maxOpenSessions  int
	auditLog         string
	auditLogDigest   string
	ratesStrict       bool
	ratesMaxStaleness int
	ingestID          string	ingestIDSet       bool
	outManifest       string
	manifestSignature string
}

func main() {
	cfg, err := parseArgs(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}
	if err := run(cfg); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func parseArgs(args []string) (cliConfig, error) {
	cfg := cliConfig{
		sessionGap:       600,
		watermarkLag:     300,
		pendingTTL:       86400,
		maxOpenSessions:  100000,
		ratesMaxStaleness: 0,
	}
	required := map[string]bool{
		"--input-dir": false,
		"--rates":     false,
		"--output":    false,
		"--rejects":   false,
	}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "--input-dir":
			cfg.inputDir = nextArg(args, &i)
		case "--rates":
			cfg.ratesPath = nextArg(args, &i)
		case "--output":
			cfg.outputPath = nextArg(args, &i)
		case "--rejects":
			cfg.rejectsPath = nextArg(args, &i)
		case "--session-gap":
			cfg.sessionGap = atoiOrError(nextArg(args, &i), "--session-gap")
		case "--watermark-lag":
			cfg.watermarkLag = atoiOrError(nextArg(args, &i), "--watermark-lag")
		case "--state-in":
			cfg.stateIn = nextArg(args, &i)
		case "--state-out":
			cfg.stateOut = nextArg(args, &i)
		case "--pending-ttl":
			cfg.pendingTTL = atoiOrError(nextArg(args, &i), "--pending-ttl")
		case "--max-open-sessions":
			cfg.maxOpenSessions = atoiOrError(nextArg(args, &i), "--max-open-sessions")
		case "--audit-log":
			cfg.auditLog = nextArg(args, &i)
		case "--audit-log-digest":
			cfg.auditLogDigest = nextArg(args, &i)
		case "--rates-strict":
			cfg.ratesStrict = true
		case "--rates-max-staleness":
			cfg.ratesMaxStaleness = atoiOrError(nextArg(args, &i), "--rates-max-staleness")
		case "--ingest-id":
			cfg.ingestID = nextArg(args, &i)
			cfg.ingestIDSet = true
		case "--out-parquet-manifest":
			cfg.outManifest = nextArg(args, &i)
		case "--manifest-signature":
			cfg.manifestSignature = nextArg(args, &i)
		default:
			return cliConfig{}, fmt.Errorf("ingest: unknown flag %s", arg)
		}
		if strings.HasPrefix(arg, "--") && arg != "--rates-strict" {
			if v, ok := required[arg]; ok {
				required[arg] = true
			}
		}
	}
	for k, ok := range required {
		if !ok {
			return cliConfig{}, fmt.Errorf("ingest: %s is required", k)
		}
	}
	if cfg.ingestIDSet {
		if len(cfg.ingestID) < 1 || len(cfg.ingestID) > 128 || !ingestIDRE.MatchString(cfg.ingestID) {
			return cliConfig{}, fmt.Errorf("ingest: --ingest-id: invalid (must match ^[A-Za-z0-9][A-Za-z0-9_.:-]*$, 1..128 chars)")
		}
	}
	if cfg.outManifest == "" && cfg.manifestSignature != "" {
		return cliConfig{}, fmt.Errorf("ingest: --manifest-signature requires --out-parquet-manifest")
	}
	if cfg.outManifest != "" && !parentDirExists(cfg.outManifest) {
		return cliConfig{}, fmt.Errorf("ingest --out-parquet-manifest parent directory does not exist")
	}
	if cfg.manifestSignature != "" && !parentDirExists(cfg.manifestSignature) {
		return cliConfig{}, fmt.Errorf("ingest --manifest-signature parent directory does not exist")
	}
	return cfg, nil
}

func nextArg(args []string, i *int) string {
	if *i+1 >= len(args) {
		panic(fmt.Errorf("ingest: missing value for %s", args[*i]))
	}
	*i++
	return args[*i]
}

func atoiOrError(s, flag string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		panic(fmt.Errorf("ingest: invalid integer for %s: %s", flag, s))
	}
	return n
}

func run(cfg cliConfig) error {
	ratesData, err := os.ReadFile(cfg.ratesPath)
	if err != nil {
		return fmt.Errorf("ingest: rates: %w", err)
	}
	ratesDigest := sha256Hex(ratesData)
	rt, err := loadRates(cfg.ratesPath)
	if err != nil {
		return err
	}
	var st *loadedState
	runIndex := 1
	if cfg.stateIn != "" {
		st, err = loadState(cfg.stateIn)
		if err != nil && !os.IsNotExist(err) {
			return err
		}
		if st != nil {
			runIndex = st.runIndex + 1
		}
	}
	events, shards, err := readInputEvents(cfg.inputDir)
	if err != nil {
		return err
	}
	seen := map[string]bool{}
	if st != nil {
		for k, v := range st.seenIds {
			seen[k] = v
		}
	}
	pending := append([]pendingEntry(nil), st.pending...)
	openSessions := map[string]carriedSession{}
	for k, v := range st.openSessions {
		openSessions[k] = v
	}
	var rejects []Reject
	var auditEntries []auditLogEntry
	bucketCounts := map[string]int{"accepted": 0, "duplicate": 0, "invalid": 0, "late": 0, "unresolved_chargeback": 0}
	shardAccepted := map[string]int{}
	var minTs, maxTs time.Time
	hasMin, hasMax := false, false
	watermark := st.maxTs
	hasWatermark := st.hasMax
	for _, raw := range events {
		ctx := newContext(raw)
		bucket := "invalid"
		reason := ""
		var ev *Event
		if raw.Invalid {
			bucket = "invalid"
			reason = "invalid_json"
		} else {
			ev, reason = parseEvent(ctx, rt, cfg.ratesStrict, cfg.ratesMaxStaleness)
			if ev != nil {
				if seen[ev.ID] {
					bucket = "duplicate"
					reason = "duplicate"
				ev = nil
				} else if ev.TS.Before(watermark) || ev.TS.Equal(watermark) {
					bucket = "late"
					reason = "late"
				ev = nil
				} else {
					bucket = "accepted"
					seen[ev.ID] = true
					shardAccepted[ev.Shard]++
					if !hasMin || ev.TS.Before(minTs) {
						minTs = ev.TS
					hasMin = true
					}
					if !hasMax || ev.TS.After(maxTs) {
						maxTs = ev.TS
					hasMax = true
					}
					if ev.TS.After(watermark) {
						watermark = ev.TS
						hasWatermark = true
					}
				}
			} else {
				bucket = "invalid"
			}
		}
		bucketCounts[bucket]++
		if bucket != "accepted" {
			rejects = append(rejects, Reject{Bucket: bucketCode(bucket), Event: raw.Raw})
		}
		auditEntries = append(auditEntries, auditLogEntry{
			Shard:  raw.Shard,
			Line:   raw.Line,
			ID:     ctx.IDStr(),
			TS:     ctx.TSString(),
			Type:   ctx.TypeString(),
			Bucket: bucket,
			Reason: reason,
			Event:  raw.Raw,
		})
	}
