	if cfg.ingestIDSet {
		id := cfg.ingestID
		ingestID = &id
	}
	return manifestOutput{
		SchemaVersion: manifestSchemaVersion,
		IngestID:      ingestID,
		RunIndex:      runIndex,
		RatesDigest:   ratesDigest,
		InputShards:   manifestShards,
		Outputs:       outputs,
		Window:        window,
